"""Byte-sequence API for the compressed payload extension.

Sequences are kept as small expression trees so that very large logical byte
objects (repetitions of a compact literal) never need to be expanded.  Only
bounded windows are ever materialised; lengths and fingerprints are derived
algebraically from the tree shape.
"""
import ast
import bisect
import hashlib
import keyword
import re

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
BASE = 257
MODULUS = 1 << 64

NAME_SOURCE = 8192
TEMPLATE_SOURCE = 65536
MAX_DEPTH = 128

_TOKEN = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z')
RANDOM_TOKEN = '<<random_string>>'


# --------------------------------------------------------------------------- #
# fingerprints
# --------------------------------------------------------------------------- #

def hash_bytes(data):
    """Exact checksum: sum((b[i]+1)*257**(n-1-i)) mod 2**64."""
    h = 0
    for value in data:
        h = (h * BASE + value + 1) & MASK
    return h


def combine(left, right):
    """Fingerprint pair (length, hash) of a concatenation."""
    (ln, lh), (rn, rh) = left, right
    if ln == 0:
        return right
    if rn == 0:
        return left
    return (ln + rn, (lh * pow(BASE, rn, MODULUS) + rh) & MASK)


def _geom(power, count):
    """(sum(power**i for i < count) mod 2**64, power**count mod 2**64)."""
    if count <= 0:
        return 1 % MODULUS if False else 0, 1
    if count == 1:
        return 1, power % MODULUS
    if count % 2 == 0:
        half, sq = _geom(power, count // 2)
        return (half * (1 + sq)) & MASK, (sq * sq) & MODULUS
    total, pw = _geom(power, count - 1)
    return (total + pw) & MASK, (pw * power) & MASK


def repeat_hash(inner_hash, inner_len, count):
    """Fingerprint hash of ``inner`` repeated ``count`` times."""
    if count <= 0 or inner_len == 0:
        return 0
    return (inner_hash * _geom(pow(BASE, inner_len, MODULUS), count)[0]) & MASK


def fingerprint(node):
    if node is None:
        node = EMPTY
    return {'n': node.length, 'h': '%016x' % node.hash}


# --------------------------------------------------------------------------- #
# sequence nodes
# --------------------------------------------------------------------------- #

class Node:
    __slots__ = ('length', '_hash')

    def __init__(self, length):
        self.length = length
        self._hash = None

    @property
    def hash(self):
        h = self._hash
        if h is None:
            h = self._hash = self.compute()
        return h

    def compute(self):
        raise NotImplementedError

    def __repr__(self):
        return '%s(%d)' % (type(self).__name__, self.length)


class Lit(Node):
    __slots__ = ('data',)

    def __init__(self, data):
        super().__init__(len(data))
        self.data = data

    def compute(self):
        return hash_bytes(self.data)


class Cat(Node):
    __slots__ = ('parts', 'offsets')

    def __init__(self, parts):
        total = 0
        for part in parts:
            total += part.length
            if total > MAX:
                raise ValueError('sequence length')
        super().__init__(total)
        self.parts = tuple(parts)
        offsets = []
        running = 0
        for part in parts:
            running += part.length
            offsets.append(running)
        self.offsets = tuple(offsets)

    def compute(self):
        h = 0
        length = 0
        for part in self.parts:
            if part.length:
                h = (h * pow(BASE, part.length, MODULUS) + part.hash) & MASK
                length += part.length
        return h


class Rep(Node):
    __slots__ = ('inner', 'count')

    def __init__(self, inner, count):
        if count < 0:
            raise ValueError('repeat count')
        if inner.length and count > MAX // inner.length:
            raise ValueError('sequence length')
        super().__init__(inner.length * count)
        self.inner = inner
        self.count = count

    def compute(self):
        return repeat_hash(self.inner.hash, self.inner.length, self.count)


class Cut(Node):
    __slots__ = ('inner', 'lo', 'hi')

    def __init__(self, inner, lo, hi):
        if not 0 <= lo <= hi <= inner.length:
            raise ValueError('slice range')
        super().__init__(hi - lo)
        self.inner = inner
        self.lo = lo
        self.hi = hi

    def compute(self):
        return hash_range(self.inner, self.lo, self.hi)[1]


EMPTY = Lit(b'')

LIT_CACHE = [Lit(bytes((value,))) for value in range(256)]


def literal(data):
    """Wrap concrete bytes."""
    if type(data) is not bytes:
        raise ValueError('bytes required')
    if not data:
        return EMPTY
    if len(data) > MAX:
        raise ValueError('sequence length')
    node = Lit(data)
    node._hash = hash_bytes(data)
    return node


def sized(node, length):
    if not isinstance(node, Node):
        raise ValueError('byte sequence required')
    if node.length != length:
        raise ValueError('length mismatch')
    return node


def size(node):
    return 0 if node is None else node.length


def concat(a, b):
    if a is None:
        a = EMPTY
    if b is None:
        b = EMPTY
    if not isinstance(a, Node) or not isinstance(b, Node):
        raise ValueError('byte sequence required')
    if a.length == 0:
        return b
    if b.length == 0:
        return a
    parts = []
    for node in (a, b):
        if isinstance(node, Cat):
            parts.extend(node.parts)
        else:
            parts.append(node)
    return Cat(parts)


def concat_all(nodes):
    """Balanced concatenation; keeps access depth logarithmic."""
    parts = []
    for node in nodes:
        if node is None:
            continue
        if not isinstance(node, Node):
            raise ValueError('byte sequence required')
        if node.length == 0:
            continue
        if isinstance(node, Cat):
            parts.extend(node.parts)
        else:
            parts.append(node)
    if not parts:
        return EMPTY
    while len(parts) > 1:
        merged = []
        for index in range(0, len(parts) - 1, 2):
            merged.append(Cat([parts[index], parts[index + 1]]))
        if len(parts) % 2:
            merged.append(parts[-1])
        parts = merged
    return parts[0]


def repeat(node, count):
    if not isinstance(node, Node):
        raise ValueError('byte sequence required')
    if type(count) is not int or count < 0:
        raise ValueError('repeat count')
    if count == 0 or node.length == 0:
        return EMPTY
    if count == 1:
        return node
    return Rep(node, count)


def cut(node, start, end):
    if not isinstance(node, Node):
        raise ValueError('byte sequence required')
    length = node.length
    lo = 0 if start is None else start
    hi = length if end is None else end
    if type(lo) is not int or type(hi) is not int:
        raise ValueError('slice endpoint')
    if not 0 <= lo <= hi <= length:
        raise ValueError('slice range')
    if lo == 0 and hi == length:
        return node
    if hi == lo:
        return EMPTY
    if isinstance(node, Lit):
        return literal(node.data[lo:hi])
    return Cut(node, lo, hi)


def byte_at(node, index):
    """Single byte access at a logical offset."""
    while True:
        if isinstance(node, Lit):
            return node.data[index]
        if isinstance(node, Cat):
            position = bisect.bisect_right(node.offsets, index)
            if position:
                index -= node.offsets[position - 1]
            node = node.parts[position]
            continue
        if isinstance(node, Rep):
            index %= node.inner.length
            node = node.inner
            continue
        if isinstance(node, Cut):
            index += node.lo
            node = node.inner
            continue
        raise ValueError('unsupported sequence')


def span(node, start, end):
    """Fingerprint pair of a bounded logical range."""
    return hash_range(node, start, end)


def hash_range(node, start, end):
    if start == end:
        return 0, 0
    if isinstance(node, Lit):
        return end - start, hash_bytes(node.data[start:end])
    if isinstance(node, Cat):
        h = 0
        length = 0
        low = start
        previous = 0
        for position, bound in enumerate(node.offsets):
            if bound <= low:
                previous = bound
                continue
            if end <= previous:
                break
            left = max(low, previous)
            right = min(end, bound)
            if right > left:
                _, part = hash_range(node.parts[position], left - previous,
                                     right - previous)
                h = (h * pow(BASE, right - left, MODULUS) + part) & MASK
                length += right - left
            previous = bound
        return length, h
    if isinstance(node, Rep):
        inner = node.inner
        step = inner.length
        total = end - start
        h = 0
        remaining = total
        position = start
        first = position % step
        if first:
            take = min(step - first, remaining)
            _, part = hash_range(inner, first, first + take)
            h = (h * pow(BASE, take, MODULUS) + part) & MASK
            position += take
            remaining -= take
        copies = remaining // step
        if copies:
            h = (h * pow(BASE, step * copies, MODULUS)
                 + repeat_hash(inner.hash, step, copies)) & MASK
            position += step * copies
            remaining -= step * copies
        if remaining:
            _, part = hash_range(inner, 0, remaining)
            h = (h * pow(BASE, remaining, MODULUS) + part) & MASK
        return total, h
    if isinstance(node, Cut):
        return hash_range(node.inner, node.lo + start, node.lo + end)
    raise ValueError('unsupported sequence')


MATERIALIZE_LIMIT = 24 * 1024 * 1024


def materialize(node, limit=MATERIALIZE_LIMIT):
    """Expand a whole sequence when it is small enough to inspect directly."""
    if node is None:
        return b''
    if not isinstance(node, Node):
        raise ValueError('byte sequence required')
    if node.length > limit:
        raise ValueError('bounded materialization')
    out = bytearray()
    _write(node, 0, node.length, out)
    return bytes(out)


def window(node, start, end):
    """Expand a bounded logical range."""
    if end - start > 65536 + 4096:
        raise ValueError('bounded materialization')
    out = bytearray()
    _write(node, start, end, out)
    return bytes(out)


def _write(node, start, end, out):
    if start >= end:
        return
    if isinstance(node, Lit):
        out += node.data[start:end]
        return
    if isinstance(node, Cat):
        previous = 0
        for position, bound in enumerate(node.offsets):
            if bound <= start:
                previous = bound
                continue
            if end <= previous:
                break
            left = max(start, previous)
            right = min(end, bound)
            if right > left:
                _write(node.parts[position], left - previous, right - previous, out)
            previous = bound
        return
    if isinstance(node, Rep):
        step = node.inner.length
        if step == 0:
            return
        if start == 0 and end == node.length and step * 8 <= end - start:
            block = bytearray()
            _write(node.inner, 0, step, block)
            out += bytes(block) * node.count
            return
        position = start
        while position < end:
            copy = position // step
            offset = position - copy * step
            stop = min(step, offset + (end - position))
            _write(node.inner, offset, stop, out)
            position += stop - offset
        return
    if isinstance(node, Cut):
        _write(node.inner, node.lo + start, node.lo + end, out)
        return
    raise ValueError('unsupported sequence')


def next_lf(node, start=0, limit=8194):
    """Offset of the next LF inside a bounded window, or -1."""
    end = min(node.length, start + limit)
    if isinstance(node, Lit):
        return node.data.find(b'\n', start, end)
    block = window(node, start, end)
    found = block.find(b'\n')
    return -1 if found < 0 else start + found


# --------------------------------------------------------------------------- #
# expressions
# --------------------------------------------------------------------------- #

def depth_of(node, limit=MAX_DEPTH):
    best = 0
    stack = [(node, 0)]
    while stack:
        current, level = stack.pop()
        if level > best:
            best = level
            if best > limit:
                return best
        for child in ast.iter_child_nodes(current):
            stack.append((child, level + 1))
    return best


class Context:
    """Shared definitions plus per-coordinate template compilation."""

    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = definitions
        self.values = {}
        for row in definitions:
            name = row[0]
            source = row[1]
            if type(name) is not str or _TOKEN.match(name) is None:
                raise ValueError('definition name')
            if keyword.iskeyword(name):
                raise ValueError('definition keyword')
            if name in self.values:
                raise ValueError('duplicate definition')
            if type(source) is not str or len(source) > NAME_SOURCE:
                raise ValueError('definition source')
            self.values[name] = self.expression(source)

    def expression(self, source):
        try:
            tree = ast.parse(source, mode='eval')
        except (SyntaxError, ValueError, MemoryError, RecursionError):
            raise ValueError('expression syntax') from None
        body = tree.body
        if depth_of(body) > MAX_DEPTH:
            raise ValueError('expression depth')
        value = self._evaluate(body)
        if not isinstance(value, Node):
            raise ValueError('expression must be bytes')
        return value

    def _evaluate(self, node):
        kind = type(node)
        if kind is ast.Constant:
            value = node.value
            if isinstance(value, bool) or value is None:
                raise ValueError('literal type')
            if isinstance(value, bytes):
                return literal(value)
            if isinstance(value, str):
                return literal(value.encode('utf-8'))
            if isinstance(value, int):
                if not 0 <= value <= MAX:
                    raise ValueError('integer literal')
                return value
            raise ValueError('literal type')
        if kind is ast.Name:
            try:
                return self.values[node.id]
            except KeyError:
                raise ValueError('unknown definition') from None
        if kind is ast.BinOp:
            op = node.op
            if isinstance(op, ast.Add):
                left = self._evaluate(node.left)
                right = self._evaluate(node.right)
                if not isinstance(left, Node) or not isinstance(right, Node):
                    raise ValueError('concatenation type')
                return concat(left, right)
            if isinstance(op, ast.Mult):
                left = self._evaluate(node.left)
                right = self._evaluate(node.right)
                if isinstance(left, Node) and isinstance(right, int):
                    return repeat(left, right)
                if isinstance(left, int) and isinstance(right, Node):
                    return repeat(right, left)
                raise ValueError('repetition type')
            raise ValueError('unsupported operator')
        if kind is ast.Subscript:
            base = self._evaluate(node.value)
            if not isinstance(base, Node):
                raise ValueError('slice subject')
            index = node.slice
            if not isinstance(index, ast.Slice):
                raise ValueError('slice form')
            if index.step is not None:
                raise ValueError('slice step')
            low = self._endpoint(index.lower)
            high = self._endpoint(index.upper)
            return cut(base, low, high)
        raise ValueError('unsupported syntax')

    def _endpoint(self, node):
        if node is None:
            return None
        if not isinstance(node, ast.Constant) or isinstance(node.value, bool) \
                or not isinstance(node.value, int):
            raise ValueError('slice endpoint')
        if not 0 <= node.value <= MAX:
            raise ValueError('slice endpoint')
        return node.value

    def random(self, coordinate, occurrence):
        source = '%s/%s/%d' % (self.seed, coordinate, occurrence)
        return hashlib.sha256(source.encode('utf-8')).hexdigest()[:20]

    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        if len(value) > TEMPLATE_SOURCE:
            raise ValueError('template source')
        if value.startswith('{{') and value.endswith('}}'):
            inner = value[2:-2].strip()
            if len(inner) > NAME_SOURCE:
                raise ValueError('expression source')
            return self.expression(inner)
        if RANDOM_TOKEN not in value:
            return literal(value.encode('utf-8'))
        pieces = value.split(RANDOM_TOKEN)
        nodes = []
        for index, piece in enumerate(pieces):
            if piece:
                nodes.append(literal(piece.encode('utf-8')))
            if index + 1 < len(pieces):
                nodes.append(literal(self.random(coordinate, index).encode('ascii')))
        return concat_all(nodes)
